    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """

    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError(f"maxsize must be an integer or None, got {type(maxsize)}")

    if maxsize is not None and maxsize < 1:
        raise ValueError(f"maxsize must be greater than 0, got {maxsize}")

    def decorator(func):
        cache = {}
        args_list = []
        args_list_index = []

        def wrapper(*args, **kwargs):
            nonlocal args_list, args_list_index
            if args not in args_list:
                args_list.append(args)
                args_list_index[args] = len(args_list) - 1
            else:
                args_list_index[args] = args_list.index(args)

            if len(args_list) > maxsize:
                for _ in range(len(args_list) - maxsize):
                    args = args_list.pop(0)
                    args_list_index[args] -= 1
                    del cache[args]

            if args not in cache:
                cache[args] = func(*args, **kwargs)
                args_list.append(args)
                args_list_index[args] = len(args_list) - 1
            else:
                cache[args] = func(*args, **kwargs)
                args_list.append(args)
                args_list_index[args] = len(args_list) - 1
            return cache[args]

        def clear():
            nonlocal cache, args_list, args_list_index
            cache = {}
            args_list = []
            args_list_index = {}

        def invalidate(args):
            nonlocal cache, args_list, args_list_index
            if args in cache:
                del cache[args]
                args_list.remove(args)
                args_list_index[args] = len(args_list) - 1

        wrapper.clear = clear
        wrapper.invalidate = invalidate
        return wrapper

