def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Sort the classes by their names
    classes.sort(key=lambda x: x.__name__)
    # Create a set to store the minimum bases
    min_bases = set()
    # Iterate over the sorted classes
    for cls in classes:
        # If the class has a base class that is not in the min_bases set, add it to the set
        if cls.__bases__ not in min_bases:
            min_bases.add(cls.__bases__)
    # Return the sorted classes
    return sorted(min_bases, key=lambda x: x.__name__)

