def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Check if path is a directory
    if not os.path.isdir(path):
        raise errors.NotADirectoryError(f"Path {path} is not a directory")

    # Check if path is a pyfs root
    try:
        pyfs = PyFS(path)
    except errors.PyFSInitError:
        raise errors.PyFSInitError(f"Failed to initialize PyFS at path {path}")

    # Validate the OCFL object
    try:
        ocfl_object = OCFLObject(pyfs)
        ocfl_object.validate()
    except errors.OCFLObjectError:
        raise errors.OCFLObjectError(f"OCFL object at path {path} is invalid")

    return True

