        for file_info, file_basename in zip(file_infos, file_basenames):
            if file_basename in files_by_basename:
                files_by_basename[file_basename].append(file_info)

        packages_data = {}
        for file_basename, file_infos in files_by_basename.items():
            package_name = file_basename.split('.xml')[0]
            package_data = {'files': []}
            for file_info in file_infos:
                if file_info.filename.endswith('_metadata.xml'):
                    metadata_info = file_info
                elif file_info.filename.endswith('_data.xml'):
                    data_info = file_info
                else:
