def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.lower() == "always":
        return None

    frequency_re = r"^(?:(\d+)\s*)?(years?|months?|weeks?|days?|hours?|minutes?|seconds?)(?:\s*until\s*(\d{4}-\d{2}-\d{2}))?$"
    match = re.match(frequency_re, frequency)
    if not match:
        raise ValueError("Invalid frequency string")

    number_str, unit, end_date_str = match.groups()
    number = int(number_str) if number_str else 1

    if unit.startswith("year"):
        duration = datetime.timedelta(days=365 * number)
    elif unit.startswith("month"):
        duration = datetime.timedelta(days=30 * number)
    elif unit.startswith("week"):
        duration = datetime.timedelta(weeks=number)
    elif unit.startswith("day"):
        duration = datetime.timedelta(days=number)
    elif unit.startswith("hour"):
        duration = datetime.timedelta(hours=number)
    elif unit.startswith("minute"):
        duration = datetime.timedelta(minutes=number)
    elif unit.startswith("second"):
        duration = datetime.timedelta(seconds=number)
    else:
        raise ValueError("Invalid frequency unit")

    if end_date_str:
        end_date = datetime.datetime.strptime(end_date_str, "%Y-%m-%d")
        return max(end_date - datetime.datetime.now(), duration)
    else:
        return duration

