def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # If single command, make it a list for simplicity
    if not isinstance(commands, list):
        commands = [commands]

    # If no current working directory specified, use the current one
    if not cwd:
        cwd = os.getcwd()

    # If no environment variables specified, use the current ones
    if not env:
        env = os.environ.copy()

    # Set up process execution
    p = subprocess.Popen(commands, cwd=cwd, env=env)
    p.stdin.write(args.encode())
    p.stdin.flush()
    p.stdin.close()

    # Handle output
    stdout = b''
    stderr = b''
    while p.returncode is None:
        output = p.stdout.read()
        if output:
            stdout += output
        if p.stderr and p.stderr.read():
            stderr += p.stderr.read()
    p.wait()

    # If verbose, print output
    if verbose:
        print(stdout.decode())
        print(stderr.decode())

    # If hide_stderr, return only stdout
    if hide_stderr:
        return stdout.decode()

    # Otherwise, return a tuple of (stdout, stderr)
    return stdout.decode(), stderr.decode()

