    if not config_filenames:
        raise ValueError("Must provide at least one configuration filename")

    configs = {}
    errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                config = yaml.safe_load(f)
                if not config:
                    raise ValueError(f"Configuration file '{config_filename}' is empty")
        except OSError as e:
            errors.append(logging.LogRecord(logging.ERROR, "Failed to open configuration file", config_filename, None, e))
            continue
        except yaml.YAMLError as e:
            errors.append(logging.LogRecord(logging.ERROR, "Failed to parse configuration file", config_filename, None, e))
            continue

        if overrides:
            try:
                config = _apply_overrides(config, overrides, config_filename)
            except ValueError as e:
                errors.append(logging.LogRecord(logging.ERROR, "Failed to apply overrides", config_filename, None, e))
                continue

        if resolve_env:
            try:
                config = _resolve_env_vars(config)
            except ValueError as e:
                errors.append(logging.LogRecord(logging.ERROR, "Failed to resolve environment variables", config_filename, None, e))
                continue

        configs[config_filename] = config

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of:

    * dict of configuration filename to corresponding parsed configuration
    * sequence of logging.LogRecord instances containing any parse errors
    """
    configs = {}
    records = []
    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                filename = os.path.basename(config_filename)
                config = yaml.safe_load(f)
                configs[filename] = config
        except Exception as e:
            records.append(logging.LogRecord("config", "info", config_filename, 0, f'Failed to load configurations from {config_filename}'))
            continue

        if overrides:
            for key, value in overrides:
                config[key] = value
        if resolve_env:
            for key, value in config:
                if isinstance(value, dict) and 'env' in value:
                    config[key] = os.environ.get(value)
                if isinstance(value, str) and 'env' in value:
                    config[key] = value.format(**os.environ)
        try:
            validate_config(config)
        except Exception as e:
            records.append(logging.LogRecord("config", "info", config_filename, 0, f'Failed to validate configurations from {config_filename}'))
            continue

