    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version_tuple: handler_class for version_tuple, handler_class in cls._protocol_version_dict.items()}

    if not isinstance(protocol_version, tuple):
        raise TypeError(f"Protocol versions must be passed as a tuple, got {type(protocol_version)} instead")

    if protocol_version not in cls._protocol_version_dict:
        return {}

    return {protocol_version: handler_class for protocol_version, handler_class in cls._protocol_version_dict.items() if protocol_version[0] == protocol_version[1]}

