def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph.

    Args:
        hist: A histogram object.
        make_value: A function to set the value of a graph's point. By default,
            it is the bin content.
        get_coordinate: Defines what the coordinate of a graph point created from
            a histogram bin will be. It can be "left" (default), "right", or
            "middle".
        field_names: Field names of the graph. Their number must be the same as
            the dimension of the result. For a make_value above, they would be
            ("x", "y_mean", "y_mean_error").
        scale: The graph's scale (unknown by default). If it is True, it uses the
            histogram scale.

    Returns:
        The resulting graph.
    """
    if not hist.is_numeric():
        raise ValueError("Histogram must contain only numeric bins")
    if make_value is None:
        make_value = lambda bin_: bin_.value
    if get_coordinate == "left":
        get_coordinate = hist.get_bin_left_coordinate
    elif get_coordinate == "right":
        get_coordinate = hist.get_bin_right_coordinate
    elif get_coordinate == "middle":
        get_coordinate = hist.get_bin_middle_coordinate
    else:
        raise ValueError("Invalid get_coordinate:", get_coordinate)
    if field_names is None:
        field_names = ("x", "y")
    if scale is None:
        scale = hist.get_scale()
    result = Graph(dim=len(field_names))
    for i, field_name in enumerate(field_names):
        result.add_axis(field_name)
    for i, bin_ in enumerate(hist.get_bins()):
        coordinate = get_coordinate(bin_)
        value = make_value(bin_)
        if len(value) != len(field_names):
            raise ValueError("Invalid make_value return value:", value)
        for i, field_name in enumerate(field_names):
            result.add_point(coordinate, value[i], {field_name: value[i]})

