def isoparse(dt_str):
    # Raise an error if the input string is empty
    if not dt_str:
        raise ValueError("Input string is empty")

    # Handle full datetime strings with date, time, and timezone offset
    full_regex = r"^\d{4}-\d{2}-\d{2}[T| ][\d:.]*[Z| ][-+]\d{2}:\d{2}$"
    if re.fullmatch(full_regex, dt_str):
        return isoparse_full(dt_str)

    # Handle non-full datetime strings with date and time
    partial_regex = r"^\d{4}-\d{2}-\d{2}[T| ][\d:.]*$"
    if re.fullmatch(partial_regex, dt_str):
        return isoparse_partial(dt_str)

    # Handle datetime strings with date only
    date_regex = r"^\d{4}-\d{2}-\d{2}$"
    if re.fullmatch(date_regex, dt_str):
        return isoparse_date(dt_str)

    # Handle other valid datetime strings
    other_regex = r"^(\d{4}-\d{2})-(\d{2}|\d{4}-(\d{2}))$"
    if re.fullmatch(other_regex, dt_str):
        return isoparse_other(dt_str)

    # If the input string is not valid, raise an error
    raise ValueError("Invalid input string")

