def set_cut_chars(self, before: bytes, after: bytes) -> None:
    """Set the bytes used to delimit slice points.

    Args:
        before: Split file before these delimiters.
        after: Split file after these delimiters.
    """

    if before is None and after is None:
        raise ValueError("At least one of 'before' or 'after' must be provided")

    self._cut_chars_before = before
    self._cut_chars_after = after

def _split_into_parts(self, file_contents: bytes) -> Iterator[bytes]:
    """Split the given bytes into parts based on the cut_chars.

    Args:
        file_contents: The bytes to split.

    Yields:
        Iterator[bytes]: The parts of the file, delimited by the cut_chars.
    """
    if not self._cut_chars_before and not self._cut_chars_after:
        yield file_contents
    else:
        start = 0
        end = 0
        while end < len(file_contents):
            end = file_contents.find(self._cut_chars_before or '', start)
            if end == -1:
                end = len(file_contents)
            else:
                end += len(self._cut_chars_before or '')
            yield file_contents[start:end]
            start = end

def split(self, file_contents: bytes, max_num_splits: int = None) -> List[bytes]:
    """Split the given bytes into parts based on the cut_chars.

    Args:
        file_contents: The bytes to split.
        max_num_splits: The maximum number of parts to split the file into.

    Returns:
        List[bytes]: The parts of the file, delimited by the cut_chars.
    """
    if max_num_splits is not None and max_num_splits < 1:
        raise ValueError("max_num_splits must be None or >= 1")

    parts = list(self._split_into_parts(file_contents))
    if max_num_splits is not None:
        parts = parts[:max_num_splits]

    return parts

