def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        document_json = json.loads(document)
        if "webfinger" not in document_json:
            raise ValueError("No webfinger entry in document JSON")
        webfinger = document_json["webfinger"]
        if "links" not in webfinger:
            raise ValueError("No links in webfinger JSON")
        links = webfinger["links"]
        for link in links:
            if "rel" in link and link["rel"] == "lrdd":
                return {
                    "lrdd_url": link["href"],
                }
        return {}
    except json.JSONDecodeError:
        pass

    # If we reach here, it means we didn't find a valid webfinger document in JSON format.
    # Let's try to parse it as an XRD document.
    parser = XRDParser()
    xrd = parser.parse_xrd(document)
    if not xrd:
        raise ValueError("No webfinger entry found in XRD document")
    return {
        "lrdd_url": xrd.find_link(rel="lrdd")["href"],
    }

