def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    :param document: The webfinger document as a string.
    :return: A Python dictionary containing the parsed webfinger information.
    """
    try:
        document_json = json.loads(document)
        return {
            "subject": document_json["subject"],
            "aliases": document_json["aliases"],
            "properties": document_json["properties"],
        }
    except json.JSONDecodeError:
        pass
    try:
        document_xrd = ElementTree.fromstring(document)
        subject = document_xrd.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject").text
        aliases = [a.text for a in document_xrd.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias")]
        properties = {
            prop.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Type").text: prop.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Value").text
            for prop in document_xrd.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Property")
        }
        return {
            "subject": subject,
            "aliases": aliases,
            "properties": properties,
        }
    except ElementTree.ParseError:
        return {}
    except Exception as e:
        logger.warning("Failed to parse Diaspora webfinger document: %s", str(e))
        return {}

