    def _flatten_dict(d, parent_key=''):
        for k, v in d.items():
            key = f'{parent_key}.{k}' if parent_key else k
            if isinstance(v, dict):
                _flatten_dict(v, key)
            else:
                flatten_dict[key] = v

    _flatten_dict(plugin_spec)
    return flatten_dict

